// boundary returns the first line start at or after pos.
func boundary(r io.ReaderAt, pos, size int64) int64 {
	if pos <= 0 {
		return 0
	}
	if pos >= size {
		return size
	}
	var one [1]byte
	for p := pos - 1; p < size; p++ {
		if _, err := r.ReadAt(one[:], p); err != nil {
			return size
		}
		if one[0] == '\n' {
			return p + 1
		}
	}
	return size
}

func ShardSum(fileName string, workers int) (ret int64, err error) {
	f, err := os.Open(fileName)
	if err != nil {
		return 0, err
	}
	defer f.Close()
	s, err := f.Stat()
	if err != nil {
		return 0, err
	}
	size := s.Size()
	per := size / int64(workers)
	resultCh := make(chan int64)
	for i := 0; i < workers; i++ {
		go func(i int) {
			begin := boundary(f, int64(i)*per, size)
			end := size
			if i != workers-1 {
				end = boundary(f, int64(i+1)*per, size)
			}
			r := io.NewSectionReader(f, begin, end)
			sum, _ := Sum6Reader(r, make([]byte, 8*1024))
			resultCh <- sum
		}(i)
	}
	for i := 0; i < workers; i++ {
		ret += <-resultCh
	}
	return ret, nil
}

